-- public.exterior_borders(p_world uuid, p_building integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.exterior_borders(p_world uuid, p_building integer)
 RETURNS TABLE(x integer, y integer, dir text)
 LANGUAGE sql
 STABLE
AS $function$
  select b.x, b.y, b.dir
  from building_tile t
  cross join lateral (values ('n'), ('s'), ('w'), ('e')) as s(side)
  cross join lateral across(t.x, t.y, s.side) a
  cross join lateral border_of(t.x, t.y, s.side) b
  where t.world_id = p_world and t.building = p_building
    and building_at(p_world, a.x, a.y) is distinct from p_building
$function$
